style:
.rbd-store-card {

    border: 0;
    cursor: pointer;
    background: transparent;
}

.rbd-store-card .card-body {

    background-color: #eceaea;

    border-radius: 15px;

    padding: 2rem;

    width: 90px;
    height: 90px;

    margin: auto;

    display: flex;
    align-items: center;
    justify-content: center;

    transition: all 0.3s ease;
}

.rbd-store-card .card-body svg {

    stroke: #a7447a;

    transition: all 0.3s ease;
}

.rbd-store-card .card-body:hover {

    background-color: #a7447a;
}

.rbd-store-card .card-body:hover svg {

    stroke: #fff;

    transform: scale(1.15);
}

.card-title {

    color: #4c4949;

    font-size: 16px;

    margin-top: 14px;

    font-weight: 500;

    line-height: 22px;
}

.default-img{
    display:inline-block;
}
.hover-img{
    display: none;
}
