style:
.card{
    border: 0;
}
.card:hover{
    cursor: pointer;
}
.card-title{
    color: #4c4949;
    font-size: 16px;
    margin-top: 14px;
}
.procure-to-pay-card .card-body{
    background-color: rgba(238, 234, 255, 1);
    border: 1px solid rgba(65, 50, 142, 0.1);
    border-radius: 15px;
    padding: 2rem;
    margin: auto;
    transition: background-color 0.3s ease; /* Smooth background color transition */
    position: relative; /* Needed to make sure the hover works properly */
}
.procure-to-pay-card .card-body:hover{
    background-color: rgba(65, 50, 142, 1);
}
.procure-to-pay-card .card-body svg{
    fill: rgba(65, 50, 142, 1);
    transition: transform 0.3s ease, fill 0.3s ease;
}
.procure-to-pay-card .card-body:hover svg{
    fill: #fff;
    transform: scale(1.2);
}
.procure-to-pay-card a {
    position: absolute; /* Make the anchor tag cover the full card */
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 1; /* Make sure anchor tag is above the .card-body */
    background: transparent; /* Ensure the anchor tag is transparent */
    pointer-events: none; /* Disable pointer events on the anchor tag */
}

/* Enable clicking the link only when hovering the card-body */
.procure-to-pay-card:hover a {
    pointer-events: auto; /* Enable anchor tag click functionality */
}

